#include <bits/stdc++.h>
using namespace std;
int m;
long long target;
vector<long long> a;
vector<bool> used;
bool solve(int sidesLeft, int startIdx, long long cur){
    if (sidesLeft == 1) return true;
    if (cur == target) return solve(sidesLeft-1, 0, 0);
    for (int i=startIdx;i<m;i++){
        if (used[i] || cur+a[i] > target) continue;
        used[i]=true;
        if (solve(sidesLeft, i+1, cur+a[i])) return true;
        used[i]=false;
    }
    return false;
}
int main(){
    int n; cin >> n;
    while(n--){
        cin >> m;
        a.assign(m,0);
        long long sum=0;
        for (int i=0;i<m;i++){ cin >> a[i]; sum += a[i]; }
        if (sum % 4 != 0) { cout << "no\n"; continue; }
        target = sum/4;
        sort(a.rbegin(), a.rend());
        if (a[0] > target) { cout << "no\n"; continue; }
        used.assign(m,false);
        cout << (solve(4,0,0) ? "yes" : "no") << "\n";
    }
}

